// missingFolderRolesText says which folders weren't found, such as
// "Couldn't find the Trash and Spam folders. Set them in Folder roles."
func missingFolderRolesText(roles []string) string {
	labels := make([]string, len(roles))
	for i, role := range roles {
		labels[i] = folderRoleLabel(role)
	}
	if len(labels) == 1 {
		return "Couldn't find the " + labels[0] + " folder. Set it in Folder roles."
	}
	return "Couldn't find the " + strings.Join(labels[:len(labels)-1], ", ") + " and " + labels[len(labels)-1] + " folders. Set them in Folder roles."
}

